ght:9%;top:9%;width:43px;height:43px;border-radius:50%;display:grid;place-items:center;background:#ffedaf;color:#f8cc62;font-size:25px;box-shadow:0 0 0 11px #ffedaf35}.cloud{position:absolute;color:#fff9;font-size:34px;filter:drop-shadow(0 3px 1px #839c9a18)}.cloud-one{left:10%;top:14%}.cloud-two{left:28%;top:7%;font-size:22px}.field-label{position:relative;text-align:center;color:#fffefa;text-shadow:0 1px 3px #6a876c40;font-size:9px;font-weight:800;letter-spacing:2px;margin:0 auto 13px}.field-label span{color:#f5e4ad;font-size:11px;padding:0 6px}.farm-grid{position:relative;z-index:2;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;width:min(100%,390px);margin:0 auto}.plot{position:relative;aspect-ratio:1.12 / 1;border:2px solid #ffffff50;border-radius:13px;background:linear-gradient(145deg,#c3976b,#ad8058);box-shadow:inset 0 -7px 0 #87624575,0 5px 8px #46674327;cursor:pointer;transition:transform .15s,filter .15s;overflow:hidden;padding:0;color:inherit;touch-action:manipulation}.plot:hover{transform:translateY(-2px);filter:brightness(1.05)}.plot:active{transform:scale(.97)}.plot:focus-visible{outline:3px solid #fff3bd;outline-offset:2px}.plot::before,.plot::after{content:"";position:absolute;left:12%;right:12%;height:2px;border-radius:4px;background:#8e674b66;top:31%;box-shadow:0 7px 0 #8e674b52,0 14px 0 #8e674b45,0 21px 0 #8e674b3b}.plot::after{left:7%;right:7%;top:8%;height:auto;bottom:8%;border:1px solid #d5b08a55;background:transparent;box-shadow:none;border-radius:9px}.plot-empty .plot-sprite{opacity:.33}.plot-watered{background:linear-gradient(145deg,#997252,#815f47);box-shadow:inset 0 -7px 0 #664b39,0 5px 8px #46674327}.plot-watered::before{background:#694f3f;box-shadow:0 7px 0 #694f3f,0 14px 0 #694f3f,0 21px 0 #694f3f}.plot-sprite{position:absolute;z-index:2;left:0;right:0;top:12%;height:64%;display:grid;place-items:center;font-size:clamp(31px,5vw,47px);filter:drop-shadow(0 3px 1px #57412a33);line-height:1;transition:all .2s}.plot-seed{f